import{c as t,Q as a,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Self-Organizing Multi-Agent Systems for Continuous Software Development","description":"","frontmatter":{"url":"https://arxiv.org/abs/2603.25928","title":"Self-Organizing Multi-Agent Systems for Continuous Software Development","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2603.25928,"authors":["Wenhan Lyu","Yue Xiao","Yixuan Zhang","Yifan Sun"],"domains":["cs.SE"],"html":"https://arxiv.org/html/2603.25928v1","pdf_path":"pdfs/2603.25928.pdf","published_date":"2026-03-26T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-03-26-self-organizing-multi-agent-continuous-software-dev-2603-25928.md","filePath":"research/papers/2026-03-26-self-organizing-multi-agent-continuous-software-dev-2603-25928.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-03-26-self-organizing-multi-agent-continuous-software-dev-2603-25928.md"};function s(i,e,l,c,u,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="self-organizing-multi-agent-systems-for-continuous-software-development" tabindex="-1">Self-Organizing Multi-Agent Systems for Continuous Software Development <a class="header-anchor" href="#self-organizing-multi-agent-systems-for-continuous-software-development" aria-label="Permalink to &quot;Self-Organizing Multi-Agent Systems for Continuous Software Development&quot;">​</a></h1><p><strong>Authors</strong>: Wenhan Lyu, Yue Xiao, Yixuan Zhang, Yifan Sun <strong>Published</strong>: March 26, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2603.25928" target="_blank" rel="noreferrer">https://arxiv.org/abs/2603.25928</a> · <a href="https://arxiv.org/html/2603.25928v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2603.25928 <strong>Categories</strong>: cs.SE <strong>PDF</strong>: <a href="https://arxiv.org/abs/2603.25928" target="_blank" rel="noreferrer">research/papers/pdfs/2603.25928.pdf</a> (12 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large Language Model-based multi-agent systems have shown promise in automating software development tasks. However, most vibe code systems focus on completing small tasks and incremental code changes, leaving persistent, continuous software development largely unexplored. We present TheBotCompany, an open-source orchestration framework for continuous multi-agent software development. TheBotCompany introduces three key innovations: (1) a three-phase state machine (Strategy to Execution to Verification) for milestone-driven development, (2) self-organizing agent teams where manager agents dynamically hire, assign, and fire worker agents based on project needs, and (3) asynchronous human oversight. We evaluate TheBotCompany on real-world software projects over multiple days of continuous development, measuring team adaptation patterns, milestone completion rates, cost efficiency, and code quality. Our results demonstrate that the self-organizing approach enables effective long-term software development with measurable progress, while the verification phase catches defects that would otherwise persist.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>TheBotCompany</strong>：open-source orchestration framework，專注於 <em>continuous</em>（跨日、持續性）multi-agent software development，補足現有 vibe code 系統只做小任務 / incremental change 的空缺。</li><li><strong>Three-phase state machine</strong>：Strategy → Execution → Verification，以 milestone-driven 方式驅動長期開發流程。</li><li><strong>Self-organizing agent teams</strong>：manager agent 依專案需求動態 <em>hire / assign / fire</em> worker agent（團隊規模與分工隨需求自我調節）。</li><li><strong>Asynchronous human oversight</strong>：人類非同步介入監督，不阻塞 agent 持續推進。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>於 real-world software projects 進行 multiple days 連續開發評估，量測四維：team adaptation patterns、milestone completion rates、cost efficiency、code quality。</li><li>Self-organizing 方式可達成有 measurable progress 的長期開發。</li><li>Verification phase 能攔截「否則會持續存在」的 defects（驗證階段對缺陷攔截有實際作用）。</li><li>⚠️ Abstract 未給出具體數字（completion rate %、cost、defect 數）；精確量化需查 PDF 全文。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><p>文件 abstract 未列明確 limitation 章節。依方法判斷的潛在弱點：</p><ul><li>評估規模僅「multiple days / real-world projects」，未說明專案數量與多樣性 → 外推性存疑。</li><li>Manager agent 的 hire/fire 決策品質高度依賴底層 LLM 能力，cost efficiency 可能對 model 選擇敏感。</li><li>Asynchronous human oversight 的介入頻率 / 成本未量化，「自主程度」邊界不清。</li><li>Verification phase 攔截 defect 的 recall（漏網缺陷）未必有 ground-truth 對照。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>Self-organizing manager→worker 模型 vs. 本 workspace fan-out 紀律</strong>：論文的 dynamic hire/assign/fire 與 <code>core.md §PROPOSE 委派</code>（原 <code>subagent-strategy.md</code>）的 Fan-out ≤4、parent↔child 通訊限制方向相反（動態擴張 vs. 靜態上限）。可作為「放寬 fan-out 上限」的對照案例，⚠️ 但本 workspace 無 manager-agent 自治生命週期機制，落地需新增 orchestration 層。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li><strong>Strategy→Execution→Verification 三相 vs. The Loop 六階段</strong>：其 Verification phase ≈ core.md 的 TEST + <code>unverified_success</code> 閘門（fresh-context verifier 攔缺陷）。論文「verification catches persistent defects」與本 workspace「確定性 gate 不經 sub-agent 中介」可互相印證。</li><li><strong>Continuous / milestone-driven 開發 vs. overnight 任務</strong>：對應 <code>claude-progress.json</code> + <code>research-hub:deep</code> + <code>autoresearch</code>（原 overnight-research，v5.1 刪除） pipeline 的跨 session 持續性概念，⚠️ 但論文以 days 為尺度的 team adaptation 目前 workspace 無對應自動化載體。</li><li>⚠️ 落地門檻：論文為框架層 proposal（TheBotCompany），引入需整套 manager-agent runtime；本 workspace 現以 skill/rule advisory + hook enforcement 為主，非 agent 自治系統，無法直接移植，僅供架構參考。</li></ul>',17)])])}const p=t(n,[["render",s]]);export{d as __pageData,p as default};
